-- Barebone CI core (SHAA-267).
--
-- Every CI keeps only what every CI has, whatever its class:
--   * ident: a short, readable, unique identifier ("CI-7K3M9Q2X", Crockford
--     base32), generated by the database. Only an administrator can change it
--     (enforced by the API, audited like any CI change);
--   * valid_from / valid_until: the validity period. A CI is *active* while
--     valid_from <= now() < valid_until (no valid_until: open-ended). "active"
--     is derived at query time, never stored;
--   * label: the display name of the CI, the value of its class's title
--     attribute (ci_classes.title_attribute_id) as text, or the ident when the
--     class has none or the CI holds no value. Derived and maintained by the
--     API; clients never write it.
-- plus the registry columns it already had (class, version, timestamps, soft delete).
--
-- The fixed columns name, hostname, ip_address, serial_number, notes, status_id,
-- environment_id, owner_id and location_id become ordinary class attributes:
--   * name (text, required) is added to every root class and becomes the title
--     attribute of every class;
--   * the other fields are added only to the classes whose CIs hold a value
--     (to the topmost such class of each lineage, so a subclass inherits it);
--   * status, environment, owner and location become lookup attributes. Their
--     rows are copied into the lookup lists "status", "environment", "owner"
--     and "location" (another key if one is taken) with the SAME ids, so a
--     stored id keeps meaning the same value. The old tables stay, unchanged
--     and no longer referenced by CIs, so owner e-mail addresses, location
--     hierarchy and similar details are kept; their endpoints are deprecated;
--   * a key already used in the class's lineage gets a suffix (name_2) and a
--     note in cmdb.schema_changes.
-- Every value is copied into the type tables and verified: per field, the
-- number of values written must equal the number of CIs that held one, or the
-- migration fails and nothing changes. Only then are the old columns dropped.
--
-- Stored UI settings (list columns, sorts, filters, dashboard widgets,
-- layouts) are rewritten to the new field names in a new settings version.
--
-- Reporting views (<area>.v_<type>) read the old columns; they are dropped
-- here and rebuilt by `shadoucmdb migrate` right after the migrations.
--
-- Operators can compare every value before and after the upgrade with
-- sql/checks/core_ci_upgrade_1_before.sql and _2_after.sql.

-- The backfills below are not edits: CIs and classes keep their updated_at.
ALTER TABLE cmdb.configuration_items DISABLE TRIGGER configuration_items_set_updated_at;
--> statement-breakpoint
ALTER TABLE cmdb.ci_classes DISABLE TRIGGER ci_classes_set_updated_at;
--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- Ident
-- ---------------------------------------------------------------------------
-- 40 random bits as 8 Crockford base32 characters (no I, L, O, U), retried
-- until unused. The unique index below is the guarantee; the loop only makes a
-- collision (one in a trillion per pair) cost a retry instead of an error.
CREATE FUNCTION cmdb.new_ci_ident() RETURNS text
LANGUAGE plpgsql VOLATILE SET search_path = cmdb, public AS $$
DECLARE
  alphabet constant text := '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
  bits bigint;
  candidate text;
BEGIN
  LOOP
    bits := ('x' || encode(substring(uuid_send(gen_random_uuid()) FROM 1 FOR 5), 'hex'))::bit(40)::bigint;
    candidate := 'CI-';
    FOR i IN 0..7 LOOP
      candidate := candidate || substr(alphabet, ((bits >> (35 - 5 * i)) & 31)::integer + 1, 1);
    END LOOP;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM cmdb.configuration_items WHERE lower(ident) = lower(candidate));
  END LOOP;
  RETURN candidate;
END;
$$;
--> statement-breakpoint

ALTER TABLE cmdb.configuration_items
  ADD COLUMN ident text,
  ADD COLUMN valid_from timestamp with time zone,
  ADD COLUMN valid_until timestamp with time zone,
  ADD COLUMN label text;
--> statement-breakpoint

-- One statement per CI, so each new ident sees the ones before it.
DO $$
DECLARE
  r record;
BEGIN
  FOR r IN SELECT id FROM cmdb.configuration_items ORDER BY created_at, id LOOP
    UPDATE cmdb.configuration_items SET ident = cmdb.new_ci_ident() WHERE id = r.id;
  END LOOP;
END;
$$;
--> statement-breakpoint

UPDATE cmdb.configuration_items SET valid_from = created_at;
--> statement-breakpoint

ALTER TABLE cmdb.configuration_items
  ALTER COLUMN ident SET DEFAULT cmdb.new_ci_ident(),
  ALTER COLUMN ident SET NOT NULL,
  ALTER COLUMN valid_from SET DEFAULT now(),
  ALTER COLUMN valid_from SET NOT NULL,
  -- Generated idents match ^CI-[0-9A-Z]{8}$; an administrator may set any of these.
  ADD CONSTRAINT configuration_items_ident_format CHECK (ident ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'),
  ADD CONSTRAINT configuration_items_validity_order CHECK (valid_until IS NULL OR valid_until > valid_from);
