-- ---------------------------------------------------------------------------
-- Stored UI settings: the new field names
-- ---------------------------------------------------------------------------
-- Built-in fields that became attributes are "attributes.<key>"; list columns
-- and sorts on the name use the label. Status, environment and location
-- filters become lookup filters; count_by_status / count_by_environment
-- widgets become count_by_lookup widgets on the migrated lists.
CREATE OR REPLACE FUNCTION pg_temp.m0016_field(p text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE p
    WHEN 'name' THEN 'attributes.name' WHEN 'status' THEN 'attributes.status'
    WHEN 'environment' THEN 'attributes.environment' WHEN 'owner' THEN 'attributes.owner'
    WHEN 'location' THEN 'attributes.location' WHEN 'hostname' THEN 'attributes.hostname'
    WHEN 'ipAddress' THEN 'attributes.ip_address' WHEN 'serialNumber' THEN 'attributes.serial_number'
    WHEN 'notes' THEN 'attributes.notes' ELSE p END;
$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION pg_temp.m0016_fields(p jsonb, columns boolean) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
  -- Mapped, first occurrence kept ("name" and "attributes.name" become one entry).
  SELECT coalesce(jsonb_agg(d.f ORDER BY d.n), '[]'::jsonb)
  FROM (
    SELECT DISTINCT ON (x.f) x.f, x.n FROM (
      SELECT CASE WHEN columns AND e.v = 'name' THEN 'label' ELSE pg_temp.m0016_field(e.v) END AS f, e.n
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(p) = 'array' THEN p ELSE '[]' END) WITH ORDINALITY AS e(v, n)
    ) x ORDER BY x.f, x.n
  ) d;
$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION pg_temp.m0016_sort(p jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE WHEN jsonb_typeof(p) = 'object' AND p->>'field' IN ('name', 'hostname', 'ipAddress', 'serialNumber', 'statusName')
              THEN jsonb_set(p, '{field}', '"label"') ELSE p END;
$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION pg_temp.m0016_filters(p jsonb) RETURNS jsonb LANGUAGE sql STABLE AS $$
  SELECT CASE WHEN jsonb_typeof(p) <> 'object' THEN p ELSE
    (p - 'statusKeys' - 'environmentKeys' - 'locationKeys') || CASE WHEN lk = '{}'::jsonb THEN '{}'::jsonb
                                                                 ELSE jsonb_build_object('lookups', lk) END
  END
  FROM (
    SELECT coalesce(jsonb_object_agg(coalesce(l.list_key, m.field), p->m.prop), '{}'::jsonb) AS lk
    FROM (VALUES ('statusKeys', 'status'), ('environmentKeys', 'environment'), ('locationKeys', 'location')) AS m(prop, field)
    LEFT JOIN m0016_lists l ON l.field = m.field
    WHERE jsonb_typeof(p->m.prop) = 'array' AND jsonb_array_length(p->m.prop) > 0
  ) x;
$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION pg_temp.m0016_search(p jsonb) RETURNS jsonb LANGUAGE sql STABLE AS $$
  SELECT CASE WHEN jsonb_typeof(p) <> 'object' THEN p ELSE
    p || jsonb_strip_nulls(jsonb_build_object(
      'filters', CASE WHEN p ? 'filters' THEN pg_temp.m0016_filters(p->'filters') END,
      'sort', CASE WHEN p ? 'sort' THEN pg_temp.m0016_sort(p->'sort') END))
  END;
$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION pg_temp.m0016_widget(w jsonb) RETURNS jsonb LANGUAGE sql STABLE AS $$
  SELECT CASE
    WHEN w->>'type' IN ('count_by_status', 'count_by_environment') THEN
      w || jsonb_build_object('type', 'count_by_lookup', 'lookupListKey',
        coalesce((SELECT l.list_key FROM m0016_lists l
                  WHERE l.field = CASE w->>'type' WHEN 'count_by_status' THEN 'status' ELSE 'environment' END),
                 CASE w->>'type' WHEN 'count_by_status' THEN 'status' ELSE 'environment' END))
    WHEN w ? 'search' THEN w || jsonb_build_object('search', pg_temp.m0016_search(w->'search'))
    ELSE w
  END;
$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION pg_temp.m0016_settings(s jsonb) RETURNS jsonb LANGUAGE sql STABLE AS $$
  SELECT s
    || CASE WHEN jsonb_typeof(s->'dashboard'->'widgets') = 'array' THEN jsonb_build_object('dashboard',
         (s->'dashboard') || jsonb_build_object('widgets',
           (SELECT coalesce(jsonb_agg(pg_temp.m0016_widget(w) ORDER BY n), '[]') FROM jsonb_array_elements(s->'dashboard'->'widgets') WITH ORDINALITY AS e(w, n))))
